38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
50	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
70	    private static final int MAX_OWNERS_PER_CITY = 50;
71	
72	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
73	    private static final int MAX_OWNERS_PER_DAY = 100;
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final TelephoneNormalizer telephoneNormalizer;
84	
85	    private final AddressNormalizer addressNormalizer;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper,
91	                                 TelephoneNormalizer telephoneNormalizer,
92	                                 AddressNormalizer addressNormalizer) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	        this.telephoneNormalizer = telephoneNormalizer;
98	        this.addressNormalizer = addressNormalizer;
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
104	        Collection<Owner> owners;
105	        if (lastName != null) {
106	            owners = this.clinicService.findOwnerByLastName(lastName);
107	        } else {
108	            owners = this.clinicService.findAllOwners();
109	        }
110	        if (owners.isEmpty()) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
119	        Owner owner = this.clinicService.findOwnerById(ownerId);
120	        if (owner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        normalizeAndValidate(ownerFieldsDto);
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
133	        owner.setNamesakeCount(countNamesakes(owner));
134	        assignHousehold(owner, ownerFieldsDto);
135	        this.clinicService.saveOwner(owner);
136	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
137	        headers.setLocation(UriComponentsBuilder.newInstance()
138	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
139	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
140	    }
141	
142	    /**
143	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
144	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
145	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
146	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
147	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
148	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
149	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
150	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
151	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
152	     *
153	     * @param ownerFieldsDto the incoming owner payload, mutated in place
154	     * @throws MissingOwnerFieldsException if any required field is missing or blank
155	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
156	     */
157	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
158	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
159	        validateRequiredFields(ownerFieldsDto);
160	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
161	        ownerFieldsDto.setTelephone(telephone);
162	        requireUniqueTelephone(telephone);
163	        requireUniqueHousehold(ownerFieldsDto);
164	        requireCityHasCapacity(ownerFieldsDto.getCity());
165	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
166	        ownerFieldsDto.setRegistrationDate(registrationDate);
167	        requireDailyLimitNotReached(registrationDate);
168	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
169	    }
170	
171	    /**
172	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
173	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
174	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
175	     *
176	     * @param ownerFieldsDto the incoming owner payload
177	     * @return the effective registration date rolled forward onto a business day
178	     */
179	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
180	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
181	        if (effective == null) {
182	            effective = LocalDate.now();
183	        }
184	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
185	            effective = effective.plusDays(1);
186	        }
187	        return effective;
188	    }
189	
190	    /**
191	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
192	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
193	     * further owner may be created for that day.
194	     *
195	     * @param registrationDate the adjusted business-day registration date of the owner being created
196	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
197	     */
198	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
199	        long createdThatDay = this.clinicService.findAllOwners().stream()
200	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
201	            .count();
202	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
203	            throw new DailyOwnerLimitExceededException(
204	                "the maximum number of owners for today has already been reached");
205	        }
206	    }
207	
208	    /**
209	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
210	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
211	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
212	     * city (e.g. {@code LON-SMI-0007}).
213	     *
214	     * @param city     the owner's city
215	     * @param lastName the owner's last name
216	     * @return the generated customer code
217	     */
218	    private String generateCustomerCode(String city, String lastName) {
219	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
220	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
221	        int sequence = (int) this.clinicService.findAllOwners().stream()
222	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
223	            .count() + 1;
224	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
225	    }
226	
227	    /**
228	     * Counts how many existing owners already share the given owner's first and last name, compared
229	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
230	     * create; it is zero when the owner's name is unique.
231	     *
232	     * @param owner the newly mapped owner about to be saved
233	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
234	     */
235	    private int countNamesakes(Owner owner) {
236	        String firstName = owner.getFirstName();
237	        String lastName = owner.getLastName();
238	        return (int) this.clinicService.findAllOwners().stream()
239	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
240	                && lastName.equalsIgnoreCase(existing.getLastName()))
241	            .count();
242	    }
243	
244	    /**
245	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
246	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
247	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
248	     *
249	     * @param ownerFieldsDto the owner payload to validate
250	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
251	     */
252	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
253	        List<String> missingFields = new ArrayList<>();
254	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
255	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
256	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
257	        requireText(missingFields, "city", ownerFieldsDto.getCity());
258	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
259	        if (!missingFields.isEmpty()) {
260	            throw new MissingOwnerFieldsException(missingFields);
261	        }
262	    }
263	
264	    private void requireText(List<String> missingFields, String fieldName, String value) {
265	        if (value == null || value.isBlank()) {
266	            missingFields.add(fieldName);
267	        }
268	    }
269	
270	    /**
271	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
272	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
273	     * (blank or {@code null}) email is left untouched, since the field is optional.
274	     *
275	     * @param email the raw email value from the request, may be {@code null}
276	     * @return the lower-cased email, or the original value when none was supplied
277	     */
278	    private String normalizeEmail(String email) {
279	        if (email == null || email.isBlank()) {
280	            return email;
281	        }
282	        return email.toLowerCase();
283	    }
284	
285	    /**
286	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
287	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
288	     * originally formatted.
289	     *
290	     * @param telephone the normalized telephone of the owner being created
291	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
292	     */
293	    private void requireUniqueTelephone(String telephone) {
294	        boolean inUse = this.clinicService.findAllOwners().stream()
295	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
296	            .anyMatch(telephone::equals);
297	        if (inUse) {
298	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
299	        }
300	    }
301	
302	    /**
303	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
304	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
305	     *
306	     * @param city the city of the owner being created
307	     * @throws OwnerCityFullException if the city already contains 50 or more owners
308	     */
309	    private void requireCityHasCapacity(String city) {
310	        long cityOwners = this.clinicService.findAllOwners().stream()
311	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
312	            .count();
313	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
314	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
315	        }
316	    }
317	
318	    /**
319	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
320	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
321	     *
322	     * @param ownerFieldsDto the incoming owner payload
323	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
324	     *                                 set {@code sharesHousehold}
325	     */
326	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
327	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
328	            return;
329	        }
330	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
331	            throw new DuplicateOwnerException(
332	                "an owner with the same last name and address already exists in this household");
333	        }
334	    }
335	
336	    /**
337	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
338	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
339	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
340	     * incidental formatting differences and abbreviation variants do not affect membership.
341	     *
342	     * @param ownerFieldsDto the incoming owner payload
343	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
344	     *         them; empty when none match
345	     */
346	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
347	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
348	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
349	        return this.clinicService.findAllOwners().stream()
350	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
351	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
352	            .toList();
353	    }
354	
355	    /**
356	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
357	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
358	     *
359	     * @param value the raw field value, may be {@code null}
360	     * @return the whitespace-collapsed value, or an empty string when {@code null}
361	     */
362	    private String collapseWhitespace(String value) {
363	        if (value == null) {
364	            return "";
365	        }
366	        return value.strip().replaceAll("\\s+", " ");
367	    }
368	
369	    /**
370	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
371	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
372	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
373	     * identifier is derived deterministically from the household's last name and address, so every member of the same
374	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
375	     * feature and still lack the identifier are backfilled so the whole household shares it.
376	     *
377	     * @param owner          the newly mapped owner about to be saved
378	     * @param ownerFieldsDto the incoming owner payload
379	     */
380	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
381	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
382	            return;
383	        }
384	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
385	        if (members.isEmpty()) {
386	            return;
387	        }
388	        String householdId = generateHouseholdId(ownerFieldsDto);
389	        owner.setHouseholdId(householdId);
390	        for (Owner member : members) {
391	            if (!householdId.equals(member.getHouseholdId())) {
392	                member.setHouseholdId(householdId);
393	                this.clinicService.saveOwner(member);
394	            }
395	        }
396	    }
397	
398	    /**
399	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
400	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
401	     * of those fields, it is identical for every owner in the same household and never changes over time.
402	     *
403	     * @param ownerFieldsDto the incoming owner payload
404	     * @return the household identifier
405	     */
406	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
407	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
408	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
409	        try {
410	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
411	            StringBuilder hex = new StringBuilder();
412	            for (int i = 0; i < 6; i++) {
413	                hex.append(String.format("%02X", digest[i]));
414	            }
415	            return "HH-" + hex;
416	        } catch (NoSuchAlgorithmException ex) {
417	            throw new IllegalStateException("SHA-256 is not available", ex);
418	        }
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
424	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
425	        if (currentOwner == null) {
426	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
427	        }
428	        currentOwner.setAddress(ownerFieldsDto.getAddress());
429	        currentOwner.setCity(ownerFieldsDto.getCity());
430	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
431	        currentOwner.setLastName(ownerFieldsDto.getLastName());
432	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
433	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
434	        this.clinicService.saveOwner(currentOwner);
435	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Transactional
440	    @Override
441	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
442	        Owner owner = this.clinicService.findOwnerById(ownerId);
443	        if (owner == null) {
444	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
445	        }
446	        this.clinicService.deleteOwner(owner);
447	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
448	    }
449	
450	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
451	    @Override
452	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
453	        Owner owner = this.clinicService.findOwnerById(ownerId);
454	        if (owner == null) {
455	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
456	        }
457	        HttpHeaders headers = new HttpHeaders();
458	        Pet pet = petMapper.toPet(petFieldsDto);
459	        owner.setId(ownerId);
460	        pet.setOwner(owner);
461	        pet.getType().setName(null);
462	        this.clinicService.savePet(pet);
463	        PetDto petDto = petMapper.toPetDto(pet);
464	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
465	            .buildAndExpand(pet.getId()).toUri());
466	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
472	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
473	        if (currentOwner != null) {
474	            Pet currentPet = this.clinicService.findPetById(petId);
475	            if (currentPet != null) {
476	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
477	                currentPet.setName(petFieldsDto.getName());
478	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
479	                this.clinicService.savePet(currentPet);
480	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
481	            }
482	        }
483	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	    }
485	
486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Override
488	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
489	        HttpHeaders headers = new HttpHeaders();
490	        Visit visit = visitMapper.toVisit(visitFieldsDto);
491	        Pet pet = new Pet();
492	        pet.setId(petId);
493	        visit.setPet(pet);
494	        this.clinicService.saveVisit(visit);
495	        VisitDto visitDto = visitMapper.toVisitDto(visit);
496	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
497	            .buildAndExpand(visit.getId()).toUri());
498	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
499	    }
500	
501	
502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
505	        Owner owner = this.clinicService.findOwnerById(ownerId);
506	        if (owner != null) {
507	            Pet pet = owner.getPet(petId);
508	            if (pet != null) {
509	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
510	            }
511	        }
512	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
513	    }
514	}
